        // Required invariants need to be manually called in tests:
        std::apply([ast](auto &...requiredInv) { (((void)(requiredInv)(ast)), ...); }, inv->GetRequired());
        (void)(*inv)(ast);
        return expected.CheckMessages(inv->ViewMessages());
    }

